create table public.site_content (id text primary key, page text not null, label text not null, value text not null);
alter table public.site_content enable row level security;
grant select on public.site_content to anon,authenticated;
grant insert,update,delete on public.site_content to authenticated;
create policy "Read site content" on public.site_content for select to anon,authenticated using(true);
create policy "Owners manage content" on public.site_content for all to authenticated using ((select auth.jwt()->'app_metadata'->>'site_admin')='true') with check ((select auth.jwt()->'app_metadata'->>'site_admin')='true');
create table public.archive_entries(id uuid primary key default gen_random_uuid(), name text not null unique, description text not null default '', image text not null default '', visible boolean not null default true, display_order integer not null default 0);
alter table public.archive_entries enable row level security;
grant select on public.archive_entries to anon,authenticated;
grant insert,update,delete on public.archive_entries to authenticated;
create policy "Read visible archive" on public.archive_entries for select to anon,authenticated using(visible);
create policy "Owners manage archive" on public.archive_entries for all to authenticated using ((select auth.jwt()->'app_metadata'->>'site_admin')='true') with check ((select auth.jwt()->'app_metadata'->>'site_admin')='true');
grant insert,update,delete on public.job_openings to authenticated;
grant select on public.job_applications to authenticated;
create policy "Owners manage jobs" on public.job_openings for all to authenticated using ((select auth.jwt()->'app_metadata'->>'site_admin')='true') with check ((select auth.jwt()->'app_metadata'->>'site_admin')='true');
create policy "Owners read applications" on public.job_applications for select to authenticated using ((select auth.jwt()->'app_metadata'->>'site_admin')='true');
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('site-images','site-images',true,10485760,array['image/png','image/jpeg','image/webp']);
create policy "Owners upload site images" on storage.objects for insert to authenticated with check(bucket_id='site-images' and (select auth.jwt()->'app_metadata'->>'site_admin')='true');

-- Initial page copy and archive content
insert into public.site_content(id,page,label,value) values ('6b7f5eb2db1a1b715c05540c','allergy-notice','Before ordering','Before ordering'),('255b0195a971f80ad3a6f35e','allergy-notice','ALLERGY NOTICE','ALLERGY NOTICE'),('c8ed728ebaf3bd346b486a5e','allergy-notice','Chunki Chip cookies and toppings vary by flavor. Product descriptions are not a complete ingredient ','Chunki Chip cookies and toppings vary by flavor. Product descriptions are not a complete ingredient or allergen statement, and recipes may change.'),('a4c6c918003d0601a799a729','allergy-notice','Our menu includes flavors made with common allergens, including wheat, milk, eggs, soy, peanuts, and','Our menu includes flavors made with common allergens, including wheat, milk, eggs, soy, peanuts, and tree nuts. Other ingredients or cross-contact may also be present during preparation.'),('76669306885b1adf9c17c313','allergy-notice','If you have a food allergy or dietary restriction, call or text us at','If you have a food allergy or dietary restriction, call or text us at'),('fa7a8fcc55560a4388a32d97','allergy-notice','before ordering so our team can discuss the current ingredients and preparation details. Please do n','before ordering so our team can discuss the current ingredients and preparation details. Please do not order if we cannot confirm a product is safe for you.'),('15809afbae678b10b064fd93','allergy-notice','We cannot guarantee that any item is free from a particular allergen. When in doubt, please avoid th','We cannot guarantee that any item is free from a particular allergen. When in doubt, please avoid the product.'),('2271a46b493fb1aab0756dca','careers','Come bake with us','Come bake with us'),('833d234c3c283b0eb216140d','careers','CAREERS','CAREERS'),('030f9a9a91f7a1dcc0e0b6ab','careers','We’re growing a cookie shop with big energy. Explore current openings or send a general application ','We’re growing a cookie shop with big energy. Explore current openings or send a general application and tell us what kind of role you’re looking for.'),('3c412b1523ef80c79a1264cb','careers','Open positions','Open positions'),('b971916e647ca027bcfc8c32','careers','Apply for this role','Apply for this role'),('5cf73ecde76ba5b5c2cc1241','careers','No specific openings posted right now','No specific openings posted right now'),('9bf09731ed3a9d169098d6f0','careers','We welcome general applications and will reach out if a fit opens up. New positions will appear here','We welcome general applications and will reach out if a fit opens up. New positions will appear here when posted.'),('9a7ecb4f50c6b2a56869eeeb','careers','Apply','Apply'),('3b4c8fa5ffed08349f8c2c4e','careers','SEND US YOUR INFO','SEND US YOUR INFO'),('3cf8dfa3de5d8c0fadb1d54a','careers','Applications are temporarily unavailable. Please call or text (603) 554-8571.','Applications are temporarily unavailable. Please call or text (603) 554-8571.'),('ecd49feba92730f8c5fca48e','catering','Make the table better','Make the table better'),('cb16f732ea6a89dc3a253290','catering','CATERING, BUT MAKE IT CHUNKI.','CATERING, BUT MAKE IT CHUNKI.'),('03d6839ab83868bd611d8da4','catering','Big cookies for the group chat, the office, birthdays, showers, team wins, and every reason to bring','Big cookies for the group chat, the office, birthdays, showers, team wins, and every reason to bring dessert.'),('20c7ad008cf1adf197501c76','catering','Call or text to plan it','Call or text to plan it'),('ac8ac2329e34aff73adc7411','catering','Order cookie boxes','Order cookie boxes'),('c113c9d031a949eb5710ad11','catering','Catering starts here','Catering starts here'),('23a118239d5e602911ae350a','catering','THE COOKIE','THE COOKIE'),('889c0a7b86abf708abc6f474','catering','CREW HAS YOU.','CREW HAS YOU.'),('e9bcc804ff686ffdc9c505c9','catering','Tell us your date, headcount, and cookie vision. We’ll help you build the right order.','Tell us your date, headcount, and cookie vision. We’ll help you build the right order.'),('2a42067dd7ed3f204a12d5e7','catering','Milford, NH','Milford, NH'),('4c239eff6bc1b80aecbdd1d2','catering','For every kind of crowd','For every kind of crowd'),('66ef580b68a433eb934b82a9','catering','CATERING OPTIONS','CATERING OPTIONS'),('51d490d4e08596ba0b66085c','catering','Fresh baked, packed with care, and ready to disappear.','Fresh baked, packed with care, and ready to disappear.'),('4817a86a247b6b8129340135','catering','Ready to grab','Ready to grab'),('d6d98af1f7046e0d658c851d','catering','INDIVIDUALLY WRAPPED','INDIVIDUALLY WRAPPED'),('029b6b48b8f4f0e69b4445ac','catering','$4 per cookie','$4 per cookie'),('302dcf92d824f2d7c04767ec','catering','Perfect for meetings, thank-yous, favor tables, and moments where every person gets their own Chunki','Perfect for meetings, thank-yous, favor tables, and moments where every person gets their own Chunki.'),('86c85ee690c38f5f3c0fcf16','catering','Put them out and watch them go','Put them out and watch them go'),('a3d7803ae5dd75a3aae461c5','catering','UNWRAPPED COOKIE TRAYS','UNWRAPPED COOKIE TRAYS'),('cd2a586c9d901400d72a2408','catering','$3.50 per cookie','$3.50 per cookie'),('fa456a01d06ed33c798278d0','catering','Built for dessert spreads, parties, and cookie tables with zero leftovers expected.','Built for dessert spreads, parties, and cookie tables with zero leftovers expected.'),('6e8018813aa03cbec36a7445','catering','How it works','How it works'),('2f4d66042876217312153f4b','catering','LET’S BUILD YOUR ORDER.','LET’S BUILD YOUR ORDER.'),('2435fc147a8da8fe13e92df4','catering','Got an event coming up?','Got an event coming up?'),('e158da11a0001c60061d0f13','catering','LET’S TALK COOKIES.','LET’S TALK COOKIES.'),('2b617962fbaec53f5fdf6bd1','flavor-archive','The vault is open','The vault is open'),('07cfa7d0c632a3f1b04710f6','flavor-archive','COOKIE FLAVOR ARCHIVE','COOKIE FLAVOR ARCHIVE'),('3d4686a582c162b441a2d5fc','flavor-archive','A running record of Chunki Chip rotations, old favorites, and flavors that deserve their comeback mo','A running record of Chunki Chip rotations, old favorites, and flavors that deserve their comeback moment.'),('696d2c4a112ad8ce5031a87a','flavor-archive','Former weekly drops','Former weekly drops'),('d5aa61f98a6f22c8fa349214','flavor-archive','THE FLAVOR FILES','THE FLAVOR FILES'),('69b81c75d69074c20c8b47ed','flavor-archive','archived flavors','archived flavors'),('9fe13a98787aee278f2994e4','flavor-archive','From the flavor archive','From the flavor archive'),('e9a152bec822717bce2dfa22','flavor-archive','Past flavor','Past flavor'),('950cae3225351efee8c02c60','flavor-archive','MORE FROM THE ARCHIVE','MORE FROM THE ARCHIVE'),('977e6150f65e0d4b9a8be8f8','flavor-archive','Past flavor','Past flavor'),('a6f58f891398b75a95080b73','flavor-archive','Want one back?','Want one back?'),('acac7c3521aa4a5ee57d3c49','flavor-archive','KEEP AN EYE ON THE WEEKLY MENU.','KEEP AN EYE ON THE WEEKLY MENU.'),('7ba6ee87c2ed6927daa7ce8c','flavor-archive','Archive favorites can always make another appearance. Check this week’s menu to see what is in the o','Archive favorites can always make another appearance. Check this week’s menu to see what is in the oven now.'),('6bc523e7d180e853173afaaf','flavor-archive','See this week’s flavors','See this week’s flavors'),('0a51368afa699efa50e19152','intellectual-property','Legal','Legal'),('2ef24d784bd55563addbe0be','intellectual-property','INTELLECTUAL','INTELLECTUAL'),('714eeef79ea9d8e7eaef3618','intellectual-property','PROPERTY','PROPERTY'),('fcf85d5fb3c04a20beda87e2','intellectual-property','All content displayed on the Chunki Chip website, including but not limited to logos, branding, prod','All content displayed on the Chunki Chip website, including but not limited to logos, branding, product names, graphics, photography, website design, text, visual assets, marketing materials, and creative elements are the intellectual property of Chunki Chip unless otherwise stated.'),('c5f70497f906036c0077de1f','intellectual-property','Unauthorized copying, reproduction, redistribution, resale, modification, or commercial use of any C','Unauthorized copying, reproduction, redistribution, resale, modification, or commercial use of any Chunki Chip intellectual property is strictly prohibited without prior written permission.'),('f08a8731e971f7c200a6a033','intellectual-property','Chunki Chip branding, visual identity, and original content may not be used in any manner that could','Chunki Chip branding, visual identity, and original content may not be used in any manner that could cause confusion, imply affiliation, or misrepresent ownership.'),('683f0b61b7b1abf8963b2aa8','intellectual-property','All trademarks, service marks, trade dress, and related branding elements remain the property of the','All trademarks, service marks, trade dress, and related branding elements remain the property of their respective owners.'),('74306cfe7cf14c738017a6c9','intellectual-property','Requests regarding licensing, media usage, partnerships, or intellectual property concerns may be di','Requests regarding licensing, media usage, partnerships, or intellectual property concerns may be directed through our contact channels.'),('d392b63957f415f18bbef241','press','Media & stories','Media & stories'),('16b8b91967fe06fb9d66add0','press','PRESS','PRESS'),('e1b8a2afec67bebba5aef44c','press','Chunki Chip is a New Hampshire cookie shop baking thick, stuffed cookies and weekly flavor drops in ','Chunki Chip is a New Hampshire cookie shop baking thick, stuffed cookies and weekly flavor drops in Milford.'),('4830d5a3124dae34cd6b793f','press','MEDIA INQUIRIES','MEDIA INQUIRIES'),('54c138337b192e75652a23d1','press','For interviews, photography requests, or press questions, call or text the shop. Please include your','For interviews, photography requests, or press questions, call or text the shop. Please include your outlet, deadline, and what you’re working on.'),('275fba957fa88ac22c5f0624','press','Call (603) 554-8571','Call (603) 554-8571'),('7ffa181f6f73ee0034682a73','privacy','Legal','Legal'),('283761d639bc3f005be94f27','privacy','PRIVACY','PRIVACY'),('0c741a7a54e6127cda83ad2c','privacy','POLICY','POLICY'),('9dcbd95b877a20ff05157d1e','privacy','Chunki Chip respects your privacy and is committed to protecting your personal information.','Chunki Chip respects your privacy and is committed to protecting your personal information.'),('8269c205e8de3d2565d87f74','privacy','We may collect information including your name, email address, shipping information, phone number, a','We may collect information including your name, email address, shipping information, phone number, and payment-related details when you place orders, join rewards programs, or interact with our website.'),('9f5e96c75d501ec15e777bb0','privacy','Payment information is securely processed through third-party payment providers including Square. Ch','Payment information is securely processed through third-party payment providers including Square. Chunki Chip does not directly store full payment card information.'),('ee4969f32d5269151c825f7b','privacy','Customer information may be used for order fulfillment, customer support, rewards programs, marketin','Customer information may be used for order fulfillment, customer support, rewards programs, marketing communications, promotions, and improving our services.'),('6b8132e021fb24ec5a53c25d','privacy','If you apply for a job, we collect the contact and experience details you submit to review your appl','If you apply for a job, we collect the contact and experience details you submit to review your application and contact you about employment. Applications are stored in our database and are not visible to the public.'),('b65ce3331a6856f7ae74d970','privacy','We do not sell customer personal information to third parties.','We do not sell customer personal information to third parties.'),('8fb52b36d5165bee5054860c','privacy','By using this website, you consent to the collection and use of information in accordance with this ','By using this website, you consent to the collection and use of information in accordance with this policy.'),('80686cb3de70af8ad09702b0','refunds','Legal','Legal'),('41348edf84c15fe308c06cb9','refunds','REFUND','REFUND'),('8ed0c88bd9925ffba997b693','refunds','POLICY','POLICY'),('91eec012866849e31e610765','refunds','Because Chunki Chip products are freshly baked and perishable, all sales are generally final once an','Because Chunki Chip products are freshly baked and perishable, all sales are generally final once an order is prepared or fulfilled.'),('b5a8a23fa67252ab8f5363a3','refunds','If your order arrives damaged, incorrect, or incomplete, please contact us as soon as possible with ','If your order arrives damaged, incorrect, or incomplete, please contact us as soon as possible with your order details and photos when applicable.'),('c5eceb4d6595ecf02e8c7199','refunds','Refunds, replacements, or store credit may be issued at our discretion depending on the situation.','Refunds, replacements, or store credit may be issued at our discretion depending on the situation.'),('86f4be1b532869e42e64bb9b','refunds','We are unable to guarantee refunds for delays caused by incorrect delivery information, missed deliv','We are unable to guarantee refunds for delays caused by incorrect delivery information, missed deliveries, weather, carrier delays, or circumstances outside our control.'),('912c2599703e6221679ab2c6','refunds','Our goal is to make every order right whenever reasonably possible.','Our goal is to make every order right whenever reasonably possible.'),('a6d31c14be77265c603c4464','reviews','Your cookie story','Your cookie story'),('d7f16fede1efa14685a39249','reviews','REVIEWS','REVIEWS'),('8c80b080d3861be17649bb0b','reviews','Tried a flavor you loved? Your honest feedback helps neighbors find us and helps us keep making the ','Tried a flavor you loved? Your honest feedback helps neighbors find us and helps us keep making the good stuff.'),('dde969685fa87d1384f68599','reviews','Read or leave a Google review','Read or leave a Google review'),('f94082aa9c01d09bc0b626a4','reviews','THANKS FOR SUPPORTING LOCAL','THANKS FOR SUPPORTING LOCAL'),('2c05207ef2b414c86de555a9','reviews','We’re keeping customer reviews on Google so you can see them in their original context. Use the link','We’re keeping customer reviews on Google so you can see them in their original context. Use the link above to read the latest feedback or leave your own.'),('02d123e2a4bf2adf969daf62','shipping','Legal','Legal'),('f22a10db9c8eb7498e130514','shipping','SHIPPING','SHIPPING'),('e809a8e71012086420afe498','shipping','POLICY','POLICY'),('5fae7838487bdaf1f7df57c3','shipping','Chunki Chip offers local delivery and nationwide shipping for eligible cookie products.','Chunki Chip offers local delivery and nationwide shipping for eligible cookie products.'),('2150fb75c97f1da6a4ca29d8','shipping','Local delivery may be fulfilled through DoorDash or another approved delivery partner. Delivery avai','Local delivery may be fulfilled through DoorDash or another approved delivery partner. Delivery availability, timing, and fees may vary by location.'),('e34e7dbea36242aa924a9830','shipping','Nationwide shipping orders are packed for freshness and shipped to the address provided at checkout.','Nationwide shipping orders are packed for freshness and shipped to the address provided at checkout. Shipping times may vary based on carrier availability, destination, weather, holidays, and order volume.'),('d59d2d167168b20b60029685','shipping','Customers are responsible for entering a complete and accurate shipping address. Chunki Chip is not ','Customers are responsible for entering a complete and accurate shipping address. Chunki Chip is not responsible for delays or failed deliveries caused by incorrect shipping information.'),('850f2a9549bb613567cb4e37','shipping','Because our products are perishable, please retrieve packages promptly after delivery.','Because our products are perishable, please retrieve packages promptly after delivery.'),('e100cd8168aae339a253eba2','terms','Legal','Legal'),('96624d916241043bac1f37c7','terms','TERMS OF','TERMS OF'),('69e46b4d538ed9db9e82e1d3','terms','SERVICE','SERVICE'),('f86b5820d60b58fd49454996','terms','By accessing or using the Chunki Chip website, you agree to comply with and be bound by these Terms ','By accessing or using the Chunki Chip website, you agree to comply with and be bound by these Terms of Service.'),('9edb080c007ecc4f87f5426a','terms','Chunki Chip reserves the right to update products, pricing, availability, shipping methods, promotio','Chunki Chip reserves the right to update products, pricing, availability, shipping methods, promotions, and website content at any time without prior notice.'),('020dd2c9618ff05af8252d10','terms','Customers agree to provide accurate information when placing orders, joining rewards programs, or su','Customers agree to provide accurate information when placing orders, joining rewards programs, or submitting contact forms.'),('08ced1d60dfea1a3241259b1','terms','Unauthorized use of this website, including attempts to interfere with functionality, scrape content','Unauthorized use of this website, including attempts to interfere with functionality, scrape content, reproduce materials, or misuse branding is prohibited.'),('138185804c5b979303b9e952','terms','Chunki Chip is not liable for indirect, incidental, or consequential damages arising from the use of','Chunki Chip is not liable for indirect, incidental, or consequential damages arising from the use of this website or our products beyond the extent permitted by law.'),('3f1810be54cb8ac609b12e2f','terms','Continued use of the website constitutes acceptance of these terms.','Continued use of the website constitutes acceptance of these terms.'),('d89e44936bfa7dcce8590698','Home','CHUNKI CHIP®','CHUNKI CHIP®'),('4da116b4eb144b507795662e','Home','Milford, NH · Fresh baked daily','Milfo